#!/usr/bin/env python3
"""Process JSONL jobs with durable, restartable checkpoints."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import sys
import tempfile


def _reject_json_constant(value):
    raise ValueError(f"invalid JSON constant: {value}")


def result_for(payload):
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    return hashlib.sha256(encoded).hexdigest()


def read_jobs(path):
    jobs = []
    ids = set()
    with path.open("r", encoding="utf-8") as source:
        for number, line in enumerate(source, 1):
            if not line.strip():
                continue
            try:
                job = json.loads(line, parse_constant=_reject_json_constant)
            except (json.JSONDecodeError, ValueError) as exc:
                raise ValueError(f"invalid JSON on input line {number}: {exc}") from exc
            if not isinstance(job, dict):
                raise ValueError(f"input line {number} is not a JSON object")
            if "id" not in job or "payload" not in job:
                raise ValueError(f"input line {number} is missing id or payload")
            job_id = job["id"]
            if not isinstance(job_id, str) or not job_id:
                raise ValueError(f"input line {number} has an invalid id")
            if job_id in ids:
                raise ValueError(f"duplicate id on input line {number}")
            result = result_for(job["payload"])
            jobs.append((job_id, result))
            ids.add(job_id)
    return jobs


def completed_from_output(path, jobs):
    """Return the number of jobs represented by the valid output prefix."""
    if not path.exists():
        return 0
    lines = path.read_text(encoding="utf-8").splitlines()
    if len(lines) > len(jobs):
        raise ValueError("output contains more records than the job file")
    for index, line in enumerate(lines):
        try:
            record = json.loads(line, parse_constant=_reject_json_constant)
        except (json.JSONDecodeError, ValueError) as exc:
            raise ValueError(f"malformed output record {index + 1}") from exc
        expected_id, expected_result = jobs[index]
        if not isinstance(record, dict) or record.get("id") != expected_id or record.get("result") != expected_result:
            raise ValueError(f"invalid output record {index + 1}")
    return len(lines)


def write_state(path, completed_ids):
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as temporary:
            json.dump({"completed_ids": completed_ids}, temporary, separators=(",", ":"))
            temporary.write("\n")
            temporary.flush()
            os.fsync(temporary.fileno())
        os.replace(temporary_name, path)
    except BaseException:
        try:
            os.unlink(temporary_name)
        except FileNotFoundError:
            pass
        raise


def nonnegative_integer(value):
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be a non-negative integer") from exc
    if parsed < 0:
        raise argparse.ArgumentTypeError("must be a non-negative integer")
    return parsed


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--jobs", required=True, type=Path)
    parser.add_argument("--state", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--fail-after", type=nonnegative_integer)
    args = parser.parse_args()

    # Fully validate input before touching either destination.
    try:
        jobs = read_jobs(args.jobs)
    except (OSError, UnicodeError, ValueError) as exc:
        print(f"worker.py: {exc}", file=sys.stderr)
        return 2

    try:
        completed_count = completed_from_output(args.output, jobs)
        completed_ids = [job_id for job_id, _ in jobs[:completed_count]]
        if args.fail_after == 0 and completed_count < len(jobs):
            return 75

        if completed_count < len(jobs):
            args.output.parent.mkdir(parents=True, exist_ok=True)
            with args.output.open("a", encoding="utf-8") as output:
                # A valid last JSON record need not have ended with a newline.
                needs_separator = args.output.stat().st_size > 0
                if needs_separator:
                    with args.output.open("rb") as existing:
                        existing.seek(-1, os.SEEK_END)
                        needs_separator = existing.read(1) not in (b"\n", b"\r")
                if needs_separator:
                    output.write("\n")
                for job_id, result in jobs[completed_count:]:
                    output.write(json.dumps({"id": job_id, "result": result}, separators=(",", ":")) + "\n")
                    output.flush()
                    os.fsync(output.fileno())
                    completed_ids.append(job_id)
                    write_state(args.state, completed_ids)
                    if args.fail_after is not None and len(completed_ids) - completed_count >= args.fail_after:
                        return 75

        # Repair missing, stale, or malformed state even when output is complete.
        write_state(args.state, completed_ids)
        return 0
    except (OSError, UnicodeError, ValueError) as exc:
        print(f"worker.py: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

